        html, body { font-family: 'Montserrat', system-ui, -apple-system, sans-serif; height:100%; overflow:hidden; overscroll-behavior:none; }
        @font-face {
          font-family: 'Gendy';
          src: url('data:font/otf;base64,') format('opentype');
          font-weight: 400;
          font-style: normal;
          font-display: swap;
        }
        @font-face {
          font-family: 'Utendo';
          src: url('data:font/woff2;base64,') format('woff2');
          font-weight: 700;
          font-style: normal;
          font-display: swap;
        }
        .font-display { font-family: 'Gendy', 'Montserrat', sans-serif; }
        .study-leave-classroom-label { font-weight: 800; }
        .study-leave-classroom-icon path { stroke-width: 3.4; }
        .no-scrollbar::-webkit-scrollbar{display:none;}
        .no-scrollbar{-ms-overflow-style:none;scrollbar-width:none;}
        .flip-card{background:linear-gradient(135deg,#e6ecf5,#ffffff);border:1px solid #dbe4f0;border-radius:1.5rem;padding:0;min-height:160px;cursor:pointer;margin-bottom:1rem;transition:transform .15s ease-in;-webkit-transform:translateZ(0);transform:translateZ(0);will-change:transform;}
        .flip-card.flipping{transform:scaleX(0.02) translateZ(0);}
        .flip-card-inner{min-height:160px;box-sizing:border-box;display:flex;align-items:flex-start;justify-content:flex-start;text-align:left;padding:1.25rem 1.5rem;}
        .feed-media{width:100%;max-height:520px;overflow:hidden;background:#f3f4f6;display:flex;align-items:center;justify-content:center;}
        .feed-media > *{width:100%;max-width:100%;max-height:520px;height:auto;object-fit:cover;}
        /* Reserve a 4:5 box until the photo loads, so the post never collapses into a blank gap. */
        .feed-media:has(> img:not(.feed-img-loaded)){aspect-ratio:4/5;}
        /* Pictures are revealed only once fully loaded (feed.js adds .feed-img-loaded), so a post
           never shows an image drawing itself in line by line */
        .feed-media img:not(.feed-img-loaded){opacity:0;animation:feedImgFailsafe 0s linear 6s forwards;}
        .feed-media img.feed-img-loaded{opacity:1;transition:opacity .15s ease;}
        @keyframes feedImgFailsafe{to{opacity:1;}}
        .post-media-carousel{width:100%;}
        .post-media-carousel > div{scroll-behavior:smooth;-webkit-overflow-scrolling:touch;}
        .post-media-carousel img, .post-media-carousel video{width:100%;height:auto;max-height:520px;object-fit:cover;}
        @media (min-width:768px){ .post-media-carousel img, .post-media-carousel video{max-height:640px;} }
        @media (min-width:1100px){
          .feed-media{max-height:640px;}
