        #auth-gate .auth-pass-wrap{position:relative;}
        #auth-gate .auth-pass-wrap input{padding-right:42px;}
        #auth-gate .auth-pass-toggle{
          position:absolute;
          top:50%;
          right:8px;
          transform:translateY(-50%);
          width:28px;
          height:28px;
          display:flex;
          align-items:center;
          justify-content:center;
          background:none;
          border:none;
          padding:0;
          cursor:pointer;
          color:#8a93a6;
