        }
        #auth-gate .auth-pass-toggle:hover{color:var(--a-royal); background:rgba(30,144,255,0.08);}
        #auth-gate .auth-pass-toggle svg{width:18px;height:18px;}
        #auth-gate .auth-row2{display:grid;grid-template-columns:1fr 1fr;gap:10px;}
        #auth-gate .auth-forgot{display:flex; justify-content:flex-end; margin:-6px 0 14px;}
        #auth-gate .auth-forgot a{font-size:11.5px; color:var(--a-royal); font-weight:600; text-decoration:none;}
        #auth-gate .auth-cta{
          width:100%;
          border:none;
          /* Fully rounded to match the pill-shaped role/intent option buttons in the "One more
             thing" onboarding */
          border-radius:9999px;
