          transition:transform .08s ease, box-shadow .08s ease, filter .08s ease;
        }
        #auth-gate .auth-cta:active{transform:translateY(1px) scale(.995); filter:brightness(.97);}
        #auth-gate .auth-divider{
          display:flex; align-items:center; gap:10px;
          margin:20px 0 16px;
          color:var(--a-muted); font-size:11px; font-weight:600;
          text-transform:uppercase; letter-spacing:.08em;
          text-align:left;
        }
        #auth-gate .auth-divider::after{content:""; flex:1; height:1px; background:var(--a-field-border);}
        #auth-gate .auth-google-cta{
          width:100%;
          display:flex; align-items:center; justify-content:center; gap:10px;
          border:1.5px solid var(--a-field-border);
          background:#fff;
          border-radius:12px;
          padding:12px;
          font-family:'Inter',sans-serif;
          font-weight:600;
          font-size:13.5px;
          color:var(--a-ink);
          cursor:pointer;
