        #auth-gate .auth-google-cta:hover{border-color:var(--a-dodger); box-shadow:0 4px 12px -6px rgba(65,105,225,0.35);}
        #auth-gate .auth-google-cta:active{transform:translateY(1px);}
        #auth-gate .auth-social-ctas{ display:flex; flex-direction:column; }
        #auth-gate .auth-google-cta{ order:1; }
        #auth-gate .auth-apple-cta{ order:2; }
        html.is-apple-platform #auth-gate .auth-google-cta{ order:2; }
        html.is-apple-platform #auth-gate .auth-apple-cta{ order:1; }
        /* Match the Google button's look exactly: flat white pill, thin gray border, black
           icon/text */
        #auth-gate .auth-apple-cta{
          width:100%;
          display:flex; align-items:center; justify-content:center; gap:10px;
          position:relative;
          border:1.5px solid var(--a-field-border);
          background:#fff;
          border-radius:12px;
          padding:12px;
          font-family:'Inter',sans-serif;
          font-weight:600;
          font-size:13.5px;
          color:var(--a-ink);
          cursor:pointer;
          margin-bottom:18px;
          transition:border-color .1s ease, box-shadow .1s ease, transform .08s ease;
        }
