        #auth-gate .auth-apple-cta:hover{border-color:var(--a-dodger); box-shadow:0 4px 12px -6px rgba(65,105,225,0.35);}
        #auth-gate .auth-apple-cta:active{transform:translateY(1px);}
        #auth-gate .auth-switch{text-align:center; font-size:12.5px; color:var(--a-muted);}
