        @keyframes skelShimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        .skel-shimmer {
          position: relative;
          overflow: hidden;
          background: #e7ebf3;
        }
        .skel-shimmer::after {
          content: '';
          position: absolute;
          inset: 0;
          transform: translateX(-100%);
          background: linear-gradient(90deg, rgba(231,235,243,0) 0%, rgba(255,255,255,0.35) 50%, rgba(231,235,243,0) 100%);
          animation: skelShimmer 1.4s ease-in-out infinite;
        }
        @media (prefers-reduced-motion: reduce) {
          .skel-shimmer::after { animation: none; display: none; }
        }

        @keyframes aiTypingBounce {
          0%, 60%, 100% { transform: translateY(0); opacity:0.5; }
          30% { transform: translateY(-4px); opacity:1; }
        }
        .ai-typing-dots { display:inline-flex; align-items:center; gap:4px; }
        .ai-typing-dots span {
          width:6px; height:6px; border-radius:9999px; background:currentColor;
          display:inline-block; animation:aiTypingBounce 1.1s ease-in-out infinite;
        }
        .ai-typing-dots span:nth-child(2){ animation-delay:0.15s; }
        .ai-typing-dots span:nth-child(3){ animation-delay:0.3s; }
        @media (prefers-reduced-motion: reduce) {
          .ai-typing-dots span { animation:none; opacity:0.8; }
        }
        .ai-msg-bubble .katex-display { margin: 0.5em 0; overflow-x: auto; overflow-y: hidden; padding-bottom: 2px; }
        .ai-msg-bubble .katex { font-size: 1em; }
        .ai-graph-plot{ box-shadow:0 1px 4px rgba(10,37,64,0.08); }
        .ai-mermaid-diagram { border: 1px solid rgba(0,0,0,0.08); }
        .ai-mermaid-diagram svg { max-width: 100%; height: auto; }
        .skel-line { border-radius: 6px; }
        .skel-avatar { border-radius: 9999px; flex-shrink: 0; }
        .skel-block { border-radius: 16px; }

        .skel-story-row { display: flex; gap: 16px; padding-bottom: 18px; margin-bottom: 20px; border-bottom: 1px solid #f1f3f7; overflow: hidden; }
        .skel-story-wrap { display: flex; flex-direction: column; align-items: center; gap: 6px; flex-shrink: 0; width: 80px; }
        .skel-story-circle { position: relative; width: 80px; height: 80px; }
        .skel-story { width: 80px; height: 80px; }
        .skel-story-badge { position: absolute; top: -2px; left: -2px; width: 28px; height: 28px; border: 3px solid #fff; box-sizing: border-box; }
        .skel-story-label { width: 56px; height: 9px; }
        .skel-post { background: #fff; border-radius: 22px; padding: 16px; margin-bottom: 14px; box-shadow: 0 1px 3px rgba(10,37,64,0.06); }
        .skel-post-head { display: flex; align-items: center; gap: 12px; margin-bottom: 14px; }
        .skel-post-avatar { width: 40px; height: 40px; }
        .skel-post-headlines { flex: 1; }
        .skel-post-headlines .skel-line { height: 9px; margin-bottom: 7px; }
        .skel-post-headlines .skel-line:last-child { margin-bottom: 0; width: 40%; }
        .skel-post-line { height: 10px; margin-bottom: 8px; }
        .skel-post-line:last-child { margin-bottom: 0; }

        /* Disables the nav bar, top bar, search bar and desktop side rail while the Home skeleton
           is on screen (see authEnterApp() in games.js and unlockBootShell() in feed.js). */
        #app-shell.boot-locked #desktop-nav,
        #app-shell.boot-locked #top-bar,
        #app-shell.boot-locked #bottom-nav {
          pointer-events: none;
          opacity: 0.55;
        }

/* Feed videos previously reused .skel-shimmer while loading, which is the same moving-
   highlight shimmer used for the page-level loading skeleton */
.feed-video-skeleton {
  background: #f3f4f6;
}
.feed-video-wrap { cursor: pointer; }
.feed-video-playbtn { transition: opacity 150ms ease; opacity: 1; }
.feed-video-wrap video::-webkit-media-controls,
.feed-video-wrap video::-webkit-media-controls-enclosure,
[id^="post-"] video::-webkit-media-controls,
[id^="post-"] video::-webkit-media-controls-enclosure,
[id^="post-"] video::-webkit-media-controls-panel,
[id^="post-"] video::-webkit-media-controls-overlay-play-button {
  display: none !important;
  -webkit-appearance: none;
}

#post-feed-list {
  scroll-snap-type: y proximity;
}
#post-feed-list [id^="post-"] {
  scroll-snap-align: start;
}
/* The first post must not snap: snapping pulled it to the top and hid the "Posts" header +
   back arrow on open */
#post-feed-list .space-y-3 > [id^="post-"]:first-child {
  scroll-snap-align: none;
}

  #landing-page{
    --royal:#4169e1;
    --dodger:#1e90ff;
    --navy:#0a2540;
    --ink:#132a45;
    --paper:#ffffff;
    --mist:#dbe4f0;
    --gold:#f0a93c;
    --green:#2fae5c;
    --red:#e0473f;
    --muted:#5c7093;
    --royal-light:#5b82ea;
    --royal-dark:#2f4fb0;
    --dodger-light:#4fa4ff;
    --dodger-dark:#0f6fd1;
    --brand-grad:linear-gradient(120deg,var(--dodger) 0%,var(--royal) 55%,var(--royal-dark) 100%);
    --brand-grad-soft:linear-gradient(120deg,var(--dodger-light) 0%,var(--royal-light) 60%,var(--royal) 100%);
    --brand-grad-deep:linear-gradient(135deg,var(--navy) 0%,var(--royal-dark) 45%,var(--dodger-dark) 100%);
    --brand-mesh:
      radial-gradient(circle at 12% 18%, rgba(30,144,255,0.55), transparent 42%),
      radial-gradient(circle at 85% 12%, rgba(65,105,225,0.5), transparent 48%),
      radial-gradient(circle at 60% 90%, rgba(10,37,64,0.4), transparent 55%),
      linear-gradient(120deg,var(--dodger) 0%,var(--royal) 55%,var(--royal-dark) 100%);
    --brand-mesh-soft:
      radial-gradient(circle at 15% 20%, rgba(255,255,255,0.35), transparent 45%),
      radial-gradient(circle at 88% 82%, rgba(30,144,255,0.3), transparent 50%),
      linear-gradient(120deg,var(--dodger-light) 0%,var(--royal-light) 60%,var(--royal) 100%);
  }
  #landing-page *,
#landing-page *::before,
#landing-page *::after{box-sizing:border-box;margin:0;padding:0;}
  #landing-page{scroll-behavior:smooth;}
  #landing-page{
    font-family:'Montserrat',system-ui,-apple-system,sans-serif;
    background:var(--paper);
    color:var(--ink);
    -webkit-font-smoothing:antialiased;
    overflow-x:hidden;
  }
  #landing-page img{max-width:100%;display:block;}
  #landing-page a{color:inherit;text-decoration:none;}
  #landing-page button{font-family:inherit;}
  #landing-page .wrap{max-width:1180px;margin:0 auto;padding:0 24px;}
  #landing-page section{position:relative;}
  #landing-page section.pad{padding:40px 0;scroll-margin-top:24px;}
  #landing-page #classroom{padding-bottom:16px;}

  #landing-page ::selection{background:var(--royal-dark);color:#fff;}

