/* ---- Auth (phone): plain back arrow, no "Back" label ---- */
@media (max-width:1099px){
  #auth-gate .auth-back{
    width:38px; height:38px; padding:0; gap:0;
    background:transparent; box-shadow:none; border-radius:0;
  }
  #auth-gate .auth-back .auth-back-chev{display:block;}
  #auth-gate .auth-back .auth-back-arrow,
  #auth-gate .auth-back .auth-back-label{display:none !important;}

  /* Phone background artwork: sits behind everything, blended softly */
  /* The artwork is pinned to the top of the screen at the size of the keyboard-closed
     viewport (--auth-bg-h, measured in games.js) */
  #auth-gate::before{
    content:"";
    position:fixed;
    top:0; left:0; right:0; bottom:auto;
    /* lvh never changes when the toolbar collapses or the keyboard opens,
       so the artwork doesn't resize or appear to move. */
    height:100vh;
    height:100lvh;
    transform:translateZ(0);
    background-position:center top;
    z-index:0;
    pointer-events:none;
    background:url('data:image/webp;base64,') center / cover no-repeat;
    opacity:.28;
  }
