  #auth-gate .auth-card{background:#ffffff;}

  /* Onboarding ("Almost there" / "One more thing"): the back arrow and the Gendy heading
     used to float directly on the swirly background artwork */
  #auth-gate.auth-compact-mode:not(.auth-verify-mode) .auth-card{
    background:#ffffff;
