.cm-tabs{background:rgba(255,255,255,.78) !important;-webkit-backdrop-filter:saturate(1.8) blur(16px);backdrop-filter:saturate(1.8) blur(16px);border-bottom-color:transparent !important;box-shadow:0 1px 0 rgba(10,37,64,.06);}
