/* ---- Notifications: banner, flat rows, filters ---- */
.nbn{position:fixed;left:12px;right:12px;top:calc(env(safe-area-inset-top,0px) + 10px);z-index:12001;max-width:440px;margin:0 auto;background:#fff;border-radius:24px;box-shadow:0 14px 40px rgba(15,23,42,.22);border:1px solid rgba(0,0,0,.05);padding:12px 14px;display:flex;align-items:center;gap:12px;cursor:pointer;animation:nbnIn .28s ease-out}
@keyframes nbnIn{from{transform:translateY(-120%);opacity:0}to{transform:none;opacity:1}}
.nbn-t{font-weight:800;font-size:15px;color:#111827;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nbn-m{font-size:13px;color:#4b5563;margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nbn-time{font-size:11px;color:#9ca3af;flex-shrink:0}
.nav-av{position:relative;flex:0 0 auto;width:46px;height:46px}
.nav-av-c{width:46px;height:46px;border-radius:50%;display:flex;align-items:center;justify-content:center;overflow:hidden;background:#e8f1ff;color:#1e90ff}
.nav-av-b{position:absolute;right:-3px;bottom:-3px;width:20px;height:20px;border-radius:50%;border:2px solid #fff;display:flex;align-items:center;justify-content:center;color:#fff}
.nrow-swipe{position:relative;overflow:hidden;border-radius:20px}
.nrow-del{position:absolute;right:0;top:0;bottom:0;width:96px;background:#ef4444;color:#fff;font-weight:800;font-size:13px;display:flex;align-items:center;justify-content:center;gap:6px}
.nrow-in{position:relative;display:flex;gap:12px;padding:12px 14px;background:#fff;transition:transform .2s ease;cursor:pointer}
.nrow-in.sel{background:rgba(65,105,225,.14)}
.nrow-t{font-size:15px;color:#111827;min-width:0}
.nrow-m{font-size:13px;color:#6b7280;line-height:1.4;margin-top:2px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow-wrap:anywhere}
.nrow-dot{width:9px;height:9px;border-radius:50%;background:#1e90ff;flex:0 0 auto}
.nfilter{display:flex;gap:8px;overflow-x:auto;padding:2px 0 4px;scrollbar-width:none}
.nfilter::-webkit-scrollbar{display:none}
.nchip{flex:0 0 auto;border-radius:999px;padding:8px 15px;font-weight:700;font-size:13px;background:#f1f3f6;color:#6b7280;white-space:nowrap}
.nchip.on{background:linear-gradient(135deg,#1e90ff,#4169e1);color:#fff}
.nsec{display:flex;align-items:center;justify-content:space-between;margin:16px 4px 8px;font-size:11px;font-weight:800;letter-spacing:.06em;color:#9ca3af;text-transform:uppercase}
.nsec button{font-size:12px;font-weight:700;letter-spacing:0;text-transform:none;color:#4169e1}
.nstitch{display:flex;gap:12px;align-items:center;background:#fff;border-radius:22px;padding:14px;box-shadow:0 4px 18px rgba(15,23,42,.08);border:1px solid rgba(0,0,0,.04);cursor:pointer}
