body.dark-mode .mh-date{background:#2b2b2b;color:#f2f2f2;}
.mh-date b{font-size:17px;line-height:1;}
.mh-date small{font-size:9.5px;font-weight:700;letter-spacing:.06em;margin-top:3px;color:#6b7280;}
body.dark-mode .mh-date small{color:#9a9a9a;}
.mh-info{flex:1;min-width:0;display:flex;flex-direction:column;}
.mh-info b{font-size:14.5px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#111827;}
body.dark-mode .mh-info b{color:#f2f2f2;}
.mh-info small{font-size:12px;color:#6b7280;margin-top:2px;}
body.dark-mode .mh-info small{color:#9a9a9a;}
.mh-act{height:34px;padding:0 16px;border-radius:999px;display:flex;align-items:center;font-size:12.5px;font-weight:700;color:#fff;background:linear-gradient(135deg,#1e90ff,#4169e1);flex-shrink:0;}
body.dark-mode .mh-act{background:linear-gradient(135deg,#1457a8,#263f8c);}
.mh-act.out{background:transparent;color:#111827;border:1px solid #d1d5db;}
body.dark-mode .mh-act.out{color:#f2f2f2;border-color:#3a3a3a;}
.mh-links{display:flex;gap:18px;padding:0 14px 12px 70px;}
.mh-links button{font-size:12px;font-weight:600;color:#6b7280;}
body.dark-mode .mh-links button{color:#9a9a9a;}
.mh-links button.red{color:#ef4444;}
.mh-fab{position:sticky;bottom:18px;align-self:flex-end;margin-top:16px;height:48px;padding:0 20px;border-radius:999px;display:flex;align-items:center;gap:8px;color:#fff;font-weight:700;font-size:14px;background:linear-gradient(135deg,#1e90ff,#4169e1);box-shadow:0 8px 20px -6px rgba(30,60,140,.5);}
body.dark-mode .mh-fab{background:linear-gradient(135deg,#1457a8,#263f8c);box-shadow:0 8px 20px -6px rgba(0,0,0,.6);}

.mj-screen{flex:1;min-height:0;display:flex;flex-direction:column;align-items:stretch;}
.mj-top{display:flex;align-items:center;gap:10px;padding:8px 14px 6px;flex-shrink:0;}
.mj-top .cu-glass{width:42px;height:42px;border-radius:999px;display:flex;align-items:center;justify-content:center;background:rgba(127,127,127,.14);color:#4b5563;flex-shrink:0;}
body.dark-mode .mj-top .cu-glass{color:#c4c4c4;}
.mj-topt{flex:1;text-align:center;font-size:15px;font-weight:700;}
.mj-head{text-align:center;padding:6px 20px 0;flex-shrink:0;}
.mj-title{font-family:'Gendy','Montserrat',sans-serif;font-weight:700;font-size:21px;line-height:1.2;word-break:break-word;}
.mj-sub{font-size:13px;color:#6b7280;margin-top:4px;line-height:1.45;}
body.dark-mode .mj-sub{color:#9a9a9a;}
.mj-center{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:0 28px;min-height:0;}
.mj-preview{position:relative;flex:1;min-height:0;margin:14px 28px 0;border-radius:26px;overflow:hidden;background:#1e1e1e;max-width:420px;width:calc(100% - 56px);align-self:center;}
.mj-off{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#9ca3af;font-size:13px;font-weight:600;}
.mj-off-av{width:96px;height:96px;border-radius:50%;background:#e5e7eb;display:flex;align-items:center;justify-content:center;overflow:hidden;}
.mj-you{position:absolute;left:12px;bottom:12px;padding:4px 10px;border-radius:999px;background:rgba(0,0,0,.5);color:#fff;font-size:11.5px;font-weight:600;}
.mj-tgls{display:flex;justify-content:center;gap:26px;padding:14px 0 6px;flex-shrink:0;}
.mj-tg{display:flex;flex-direction:column;align-items:center;gap:5px;}
.mj-tg-b{width:50px;height:50px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#2b2b2b;color:#fff;}
body:not(.dark-mode) .mj-tg-b{background:#2b2b2b;color:#fff;}
body.dark-mode .mj-tg-b{background:#f2f2f2;color:#121212;}
.mj-tg.off .mj-tg-b{background:rgba(127,127,127,.18);color:#4b5563;}
body.dark-mode .mj-tg.off .mj-tg-b{color:#c4c4c4;}
.mj-tg small{font-size:11px;font-weight:600;color:#6b7280;}
body.dark-mode .mj-tg small{color:#9a9a9a;}
.mj-panel{flex-shrink:0;margin:8px 12px calc(env(safe-area-inset-bottom,0px) + 14px);padding:16px 14px 14px;border-radius:30px;background:#fff;border:1px solid #e5e7eb;box-shadow:0 12px 36px rgba(0,0,0,.10);}
body.dark-mode .mj-panel{background:#1e1e1e;border-color:#2b2b2b;box-shadow:none;}
@media (min-width:700px){.mj-panel{width:100%;max-width:440px;align-self:center;}}
.mj-label{font-size:13px;color:#6b7280;margin:0 2px 10px;}
body.dark-mode .mj-label{color:#9a9a9a;}
.mj-link{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;padding:12px 14px;border-radius:14px;background:#eef1f5;font-size:13px;color:#1e90ff;text-align:left;}
body.dark-mode .mj-link{background:#2b2b2b;color:#5eb1ff;}
.mj-link span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.mj-share,.mj-join{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;height:50px;border-radius:999px;color:#fff;font-weight:700;font-size:15px;background:linear-gradient(135deg,#1e90ff,#4169e1);}
.mj-share{margin-top:12px;}
body.dark-mode .mj-share,body.dark-mode .mj-join{background:linear-gradient(135deg,#1457a8,#263f8c);}
.mj-out{width:100%;height:50px;margin-top:10px;border-radius:999px;border:1px solid #d1d5db;font-weight:600;font-size:14px;}
body.dark-mode .mj-out{border-color:#3a3a3a;}

/* ---- Rebuilt call controls: pill bar (video, meeting, class) and labelled panel (voice). Overrides the older call-bar rules above. ---- */
