#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-pillbar .cu-ctl-label{display:none !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-pillbar .cu-ctl-btn{width:46px !important;height:46px !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-pillbar > button.cu-ctl.end{border-radius:50% !important;background:transparent !important;box-shadow:none !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-pillbar > button.cu-ctl.end .cu-ctl-btn{width:46px !important;height:46px !important;background:#ef4444 !important;color:#fff !important;box-shadow:none !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-voicegrid{display:grid !important;grid-template-columns:repeat(4,minmax(0,1fr)) !important;gap:6px !important;align-items:start !important;width:100% !important;max-width:420px !important;padding:16px 10px 14px !important;border-radius:28px !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-voicegrid > button.cu-ctl{flex:none !important;width:100% !important;min-width:0 !important;height:auto !important;gap:6px !important;margin:0 !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-voicegrid .cu-ctl-btn{width:56px !important;height:56px !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-voicegrid > button.cu-ctl.end{background:transparent !important;border-radius:0 !important;box-shadow:none !important;flex-direction:column !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-voicegrid > button.cu-ctl.end .cu-ctl-btn{width:56px !important;height:56px !important;background:#ef4444 !important;color:#fff !important;box-shadow:none !important;}
#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-voicegrid .cu-ctl-label{display:block !important;font-size:10.5px !important;font-weight:600 !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-pillbar{display:flex !important;flex-wrap:nowrap !important;justify-content:center !important;align-items:center !important;gap:10px !important;width:auto !important;max-width:100% !important;padding:8px !important;border-radius:999px !important;background:var(--cu-sheet) !important;-webkit-backdrop-filter:none !important;backdrop-filter:none !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-pillbar > button.cu-ctl{flex:0 0 auto !important;width:auto !important;height:auto !important;min-width:0 !important;gap:0 !important;margin:0 !important;padding:0 !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-pillbar .cu-ctl-label{display:none !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-pillbar .cu-ctl-btn{width:46px !important;height:46px !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-pillbar > button.cu-ctl.end{border-radius:50% !important;background:transparent !important;box-shadow:none !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-pillbar > button.cu-ctl.end .cu-ctl-btn{width:46px !important;height:46px !important;background:#ef4444 !important;color:#fff !important;box-shadow:none !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-voicegrid{display:grid !important;grid-template-columns:repeat(4,minmax(0,1fr)) !important;gap:6px !important;align-items:start !important;width:100% !important;max-width:420px !important;padding:16px 10px 14px !important;border-radius:28px !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-voicegrid > button.cu-ctl{flex:none !important;width:100% !important;min-width:0 !important;height:auto !important;gap:6px !important;margin:0 !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-voicegrid .cu-ctl-btn{width:56px !important;height:56px !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-voicegrid > button.cu-ctl.end{background:transparent !important;border-radius:0 !important;box-shadow:none !important;flex-direction:column !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-voicegrid > button.cu-ctl.end .cu-ctl-btn{width:56px !important;height:56px !important;background:#ef4444 !important;color:#fff !important;box-shadow:none !important;}
#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-voicegrid .cu-ctl-label{display:block !important;font-size:10.5px !important;font-weight:600 !important;}
@media (min-width:1100px){
  #call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-pillbar,
  #lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-pillbar{gap:14px !important;padding:10px 14px !important;}
  #call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar#call-controls-bar .cu-bar-inner.cu-pillbar .cu-ctl-btn,
  #lecture-controls-bar#lecture-controls-bar#lecture-controls-bar#lecture-controls-bar .cu-bar-inner.cu-pillbar .cu-ctl-btn,
