  body:not(.dark-mode) #career-searchbar,
  body:not(.dark-mode) #career-filterbar,
  body:not(.dark-mode) #inbox-titlebar,
  body:not(.dark-mode) #inbox-searchbar,
  body:not(.dark-mode) #inbox-filterbar{ background:#ffffff !important; background-color:#ffffff !important; }

  /* Other pages: sticky bars and page wrappers that used the grey-white */
  body:not(.dark-mode) #screen .sticky.bg-gray-50,
  body:not(.dark-mode) #screen .bg-gray-50.sticky,
  body:not(.dark-mode) #overlay > .bg-gray-50,
  body:not(.dark-mode) #overlay .flex-1.bg-gray-50,
  body:not(.dark-mode) #overlay > div > .bg-gray-50{ background-color:#ffffff !important; }

  /* Rows, covers and sticky headers */
  body:not(.dark-mode) .nrow-in{ background:#ffffff !important; }
  body:not(.dark-mode) .nrow-in.sel{ background:rgba(65,105,225,.14) !important; }
  body:not(.dark-mode) .classroom-slide-cover{ background:#ffffff !important; }
  body:not(.dark-mode) #overlay .pa-flow .pa-sticky,
  body:not(.dark-mode) #overlay .ov-sticky-head,
  body:not(.dark-mode) #overlay .ov-sticky-wrap,
  body:not(.dark-mode) #overlay div:has(> .ov-sticky-head:only-child){ background:transparent !important; }

  /* Fade strips behind sticky headers and bottom action bars */
  body:not(.dark-mode) #overlay .pa-flow .pa-sticky::before,
  body:not(.dark-mode) #overlay .ov-sticky-head::before,
  body:not(.dark-mode) #overlay .ov-sticky-wrap::before,
  body:not(.dark-mode) #overlay div:has(> .ov-sticky-head:only-child)::before{
    background:linear-gradient(to bottom,#ffffff 0,#ffffff calc(100% - 22px),rgba(255,255,255,.85) calc(100% - 12px),rgba(255,255,255,0) 100%) !important; }
  body:not(.dark-mode) .cd-actions{ background:linear-gradient(to top,#ffffff 0,#ffffff 55%,rgba(255,255,255,0) 100%) !important; }

  /* Pro / subscribe pages, Match history, onboarding-style bottom bars */
  body:not(.dark-mode) .mh-wrap{ background:#ffffff !important; }
  body:not(.dark-mode) .mh-card:before{ box-shadow:0 0 0 4px #ffffff !important; }
  body:not(.dark-mode) #careerSubscribeModal.pro-page,
  body:not(.dark-mode) #careerSubscribeModal.pro-page .ov-sticky-head,
  body:not(.dark-mode) #careerSubscribeModal.pro-page .pro-sticky-head{ background:#ffffff !important; }
  body:not(.dark-mode) .pro2-cta,
  body:not(.dark-mode) .pro3-bar{ background:linear-gradient(180deg,rgba(255,255,255,0),#ffffff 30%) !important; }
  body:not(.dark-mode) .pro4-cta{ background:#ffffff !important; }
}

/* Profile page: username sits under the full name, small, light and black */
.ph-username{ font-family:'Inter',sans-serif; font-size:12.5px; font-weight:300; line-height:1.3; color:#000000; margin:2px 0 10px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
body.dark-mode .ph-username{ color:#ffffff; }

/* Profile page: the settings gear floats on its own small round panel */
.ph-gear-panel{ width:44px; height:44px; border-radius:50%; background:#ffffff; border:0; box-shadow:0 4px 16px rgba(30,60,140,.16), 0 1px 3px rgba(30,60,140,.08); flex-shrink:0; -webkit-tap-highlight-color:transparent; transition:transform .15s ease; }
.ph-gear-panel:active{ transform:scale(.94); }
.ph-gear-panel svg{ width:22px; height:22px; }
body.dark-mode .ph-gear-panel{ background:#1e1e1e; box-shadow:none; }

/* Contact info, Telegram style: floating round back button, simple action tiles, grouped rows */
.cp-float-back{ position:absolute; left:14px; top:calc(var(--top-safe-pad,20px) + 4px); width:42px; height:42px; border-radius:9999px; display:flex; align-items:center; justify-content:center; background:rgba(120,125,135,.16); -webkit-backdrop-filter:blur(14px); backdrop-filter:blur(14px); border:0; }
.cp-tg-row{ gap:8px; }
.cp-tg svg{ width:22px !important; height:22px !important; flex-shrink:0; }
.cp-tg{ flex:1; min-width:0; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:6px; padding:12px 2px 10px; border-radius:16px; border:0; background:rgba(128,128,128,.12); color:#1E90FF; }
.cp-tg svg{ fill:none !important; stroke:currentColor !important; }
.cp-tg span{ font-size:11.5px; font-weight:500; line-height:1; color:#374151; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:100%; }
html.dark-mode .cp-tg span, body.dark-mode .cp-tg span{ color:#e5e7eb; }
html.dark-mode .cp-tg, body.dark-mode .cp-tg{ color:#5cb0ff; }
.cp-list.cp-grp{ background:rgba(128,128,128,.1) !important; border-radius:16px !important; padding:0 16px !important; }

/* Chat header, Telegram style: floating pills (back / contact / call + menu) */
.cv-tg-head{ background:transparent; }
.cv-pill{ background:rgba(120,125,135,.14); -webkit-backdrop-filter:blur(14px); backdrop-filter:blur(14px); border-radius:9999px; border:0; }
.cv-pill-round{ width:44px; height:44px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }
.cv-pill-main{ display:flex; align-items:center; gap:10px; height:48px; padding:4px 18px; }
.cv-pill-acts{ height:44px; padding:0 6px; gap:2px; }
.cv-act{ width:40px; height:40px; display:flex; align-items:center; justify-content:center; }
.cv-pill-acts{ padding:0 8px; gap:0; }

/* Settings top tiles, Telegram style: flat, centred icon + title + sub, no shadow or faded corner icon */
.stg-tg{ display:flex; flex-direction:column; align-items:center; justify-content:center; gap:4px; padding:14px 6px 12px; border-radius:14px; border:0; background:rgba(128,128,128,.12); text-align:center !important; min-width:0; }
.stg-tg-ico{ color:#1E90FF; display:flex; }
html.dark-mode .stg-tg-ico, body.dark-mode .stg-tg-ico{ color:#5cb0ff; }
.stg-tg .stg-tg-t{ font-size:12.5px; font-weight:600; max-width:100%; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-top:4px; }
.stg-tg .stg-tg-s{ font-size:11.5px; max-width:100%; }
.stg-tg:active{ opacity:.7; }

/* Selected pills: outline only, no blue glow underneath (same everywhere) */
.filter-pill.on, .outline-pill.on, .outline-pill.is-selected, .auth-intent-chip.on, .cu-handpill.on, .cu-ctl.on .cu-ctl-btn,
html.dark-mode .filter-pill.on, body.dark-mode .filter-pill.on, html.dark-mode .outline-pill.on, body.dark-mode .outline-pill.on,
body.dark-mode .outline-pill.is-selected, html.dark-mode .auth-intent-chip.on, body.dark-mode .auth-intent-chip.on,
body:not(.dark-mode) .cu-handpill.on, body.dark-mode .cu-handpill.on, body:not(.dark-mode) .cu-ctl.on .cu-ctl-btn, body.dark-mode .cu-ctl.on .cu-ctl-btn{ box-shadow:none !important; }


/* ---- Chat header, WhatsApp style: one flat bar (back, avatar, name + status, call icons), no floating pills ---- */
.cv-wa-head{ background:#f9fafb; border-bottom:1px solid rgba(128,128,128,.18); }
body.dark-mode .cv-wa-head, html.dark-mode .cv-wa-head{ background:#121212; border-bottom-color:rgba(255,255,255,.08); }
.cv-wa-back{ width:44px; height:44px; display:flex; align-items:center; justify-content:center; flex-shrink:0; background:transparent; border:0; }
.cv-wa-main{ display:flex; align-items:center; gap:10px; min-width:0; padding:2px 6px 2px 2px; }
.cv-wa-avatar{ width:38px; height:38px; border-radius:9999px; overflow:hidden; flex-shrink:0; display:flex; align-items:center; justify-content:center; background:rgba(128,128,128,.18); }
.cv-wa-avatar img{ width:100%; height:100%; object-fit:cover; }
.cv-wa-acts{ gap:0; }
.cv-wa-acts .cv-act{ width:40px; height:44px; background:transparent; }
/* WhatsApp-matched header: 56dp bar, 38dp avatar, call/video/menu spacing */
.cv-wa-acts .cv-act:nth-child(1){ width:48px; }
.cv-wa-acts .cv-act:nth-child(2){ width:44px; }
