.filter-pill.on{ border-color:#1e90ff !important; }
body.dark-mode .filter-pill, html.dark-mode .filter-pill{ box-shadow:none !important; border-color:rgba(255,255,255,.18) !important; }
body.dark-mode .filter-pill.on, html.dark-mode .filter-pill.on{ border-color:#1e90ff !important; }

/* ---- Help Center "Still stuck?" card: same look as the minimized call card (white card, soft border + shadow, dark round button) ---- */
.sp-still{ background:#fff !important; color:#111827 !important; border:1px solid rgba(0,0,0,0.06) !important; border-radius:16px; box-shadow:0 10px 30px rgba(0,0,0,0.18) !important; }
