.sp-still span span{ color:#6b7280; opacity:1; }
.sp-still .sp-go{ background:#111827; color:#fff; }
body.dark-mode .sp-still, html.dark-mode .sp-still{ background:#1e1e1e !important; color:#fff !important; border:1px solid rgba(255,255,255,0.08) !important; box-shadow:0 10px 30px rgba(0,0,0,0.5) !important; }
body.dark-mode .sp-still b, html.dark-mode .sp-still b{ color:#fff; }
body.dark-mode .sp-still span span, html.dark-mode .sp-still span span{ color:#9a9a9a; }
body.dark-mode .sp-still .sp-go, html.dark-mode .sp-still .sp-go{ background:#fff; color:#111827; }

/* ---- Bottom panels / sheets: Colmeak font for everything inside (share, menus, comments, confirm sheets) ---- */
