/* ---- Collaboration header call button + dropdown menu ---- */
.cv-wa-acts .cv-act.cv-act-callgrp{ width:62px !important; gap:1px; }
.cv-wa-acts .cv-act:nth-child(2):last-child{ width:40px; }
.cv-cm-wrap{ position:fixed; inset:0; z-index:40; background:transparent; }
.cv-cm{ position:absolute; right:10px; min-width:236px; max-width:calc(100% - 20px); background:#fff; color:#1f2937; border-radius:18px; padding:6px 0; box-shadow:0 10px 32px rgba(15,30,70,.22), 0 2px 6px rgba(15,30,70,.08); animation:ddIn .14s ease both; transform-origin:top right; }
.cv-cm-row{ display:flex; align-items:center; gap:18px; width:100%; padding:0 20px; height:52px; font-size:16px; font-weight:400; text-align:left; background:transparent; border:0; color:inherit; }
