/* ---- Select people sheet ---- */
.gc-wrap{ position:fixed; inset:0; z-index:60; background:rgba(0,0,0,.4); display:flex; align-items:flex-end; }
.gc-sheet{ width:100%; max-height:78vh; display:flex; flex-direction:column; background:#fff; color:#1f2937; border-radius:22px 22px 0 0; padding:8px 16px calc(env(safe-area-inset-bottom,0px) + 16px); }
