/* Contact info: floating "more" button + Telegram-style floating action menu */
.cp-float-more{ position:absolute; right:14px; top:calc(var(--top-safe-pad,20px) + 4px); width:42px; height:42px; border-radius:9999px; display:flex; align-items:center; justify-content:center; background:rgba(120,125,135,.16); -webkit-backdrop-filter:blur(14px); backdrop-filter:blur(14px); border:0; color:#1E90FF; z-index:2; }
