.cp-menu{ position:fixed; min-width:210px; padding:6px; border-radius:20px; background:rgba(255,255,255,.88); -webkit-backdrop-filter:blur(22px) saturate(1.6); backdrop-filter:blur(22px) saturate(1.6); box-shadow:0 12px 40px rgba(10,37,64,.22), 0 2px 8px rgba(10,37,64,.1); border:1px solid rgba(10,37,64,.06); transform-origin:top right; animation:cpMenuIn .16s cubic-bezier(.22,1,.36,1); }
